mapper.select:
SELECT bd.diary_no, bd.baby_no, bd.diary_date, bd.photo_file_name, bd.content, bd.reg_time, bd.mod_time
FROM tbl_baby_diary bd
JOIN tbl_baby_info bi ON bd.baby_no = bi.baby_no
WHERE bd.baby_no = #{babyNo} AND bi.email = #{email}
ORDER BY bd.diary_date DESC, bd.diary_no DESC
LIMIT #{size} OFFSET #{skip}

mapper.update:
UPDATE tbl_baby_diary
SET content = #{diary.content},
photo_file_name = #{diary.photoFileName}
WHERE diary_no = #{diary.diaryNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})

mapper.delete:
DELETE FROM tbl_baby_diary
WHERE diary_no = #{diaryNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})

DELETE FROM tbl_baby_diary
WHERE baby_no = #{babyNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})
